1	/*
2	 * The panel beside a map that is being generated.
3	 *
4	 * It holds more than the panel beside a stored map does — the Verify door's
5	 * answer, every refusal, what the run cost, the one edit that needs the model,
6	 * and the panel itself — so it is the one panel in this product that scrolls as
7	 * a whole rather than section by section.
8	 *
9	 * **Why as a whole.** A panel whose sections each scroll inside themselves hides
10	 * things twice over: a refusal can scroll out of the strip while the strip is
11	 * itself scrolled out of the panel, and a reader who looks away for a minute of
12	 * a run cannot tell what they have missed. Scrolling once means there is one
13	 * place to be, and everything that arrived is somewhere above or below it.
14	 */
15	
16	.dock--generation {
17	  overflow-y: auto;
18	}
19	
20	/* Inside a panel that scrolls as a whole, the section that reads out whatever is
21	 * selected is as tall as what is in it, like every other section. Left to its
22	 * own scrolling it would be a box inside a box, and the reader would have to
23	 * find which of the two was under the pointer. */
24	.dock--generation .inspector {
