/* ---- The map screen ----------------------------------------------------- *
 * A bar across the top, the map filling everything under it, and one line at
 * the foot saying where every number on it came from. No padding around the
 * map: the map is the screen. */

.page--map {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  height: 100%;
  min-height: 0;
  padding: 0;
}

.map-bar {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border-bottom: 1px solid var(--hairline);
  background: var(--surface-raised);
}

/* A word with an arrow in front of it, not a button with a fill. The only thing
 * on this bar that does anything, so it does not need to shout. */
.map-bar__back {
  padding: 0;
  margin: 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: var(--text-sm);
  color: var(--text-muted);
  cursor: pointer;
}

.map-bar__back:hover {
  color: var(--text);
}

.map-bar__title {
  margin: 0;
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  letter-spacing: -0.01em;
  color: var(--text);
}

/* The map and the panel beside it, filling everything between the bar at the
 * top and the line at the foot. The map takes what is left when the panel has
 * had its width: the panel's job is to answer one question at a time, and a
 * panel that grew with the window would make a short answer look like a page. */
.map-body {
  flex: 1 1 auto;
  display: flex;
  align-items: stretch;
  min-height: 0;
}

/* The map and the line under it that says what the last keystroke did. Both are
 * the stage; the panel is beside them. The stage is the thing the two overlays —
 * the command palette and the shortcuts sheet — are positioned against, so that
 * neither can ever cover the panel and neither needs a scrim to sit above. */
.map-stage {
  position: relative;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

/* One line under the map naming what the last keystroke did: which wire it took
 * and how long that wire's delay is, or that there was no wire that way. A
 * movement you cannot account for is the same failure as a number you cannot
 * account for, in a smaller place. */
