file.content:
  border-radius: 2px;
  color: var(--text);
}

.map-bar__sheet {
  margin: 0;
  padding: 0;
  border: none;
  background: none;
  font-family: inherit;
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.map-bar__sheet:hover {
  color: var(--text);
}

/* Where every number on the map came from, under the map — and whatever is
 * still on its way. A map whose numbers cannot say where they came from is the
 * state this product refuses to show, so the sentence is part of the map rather
 * than a footnote somebody might have left off.
 *
 * One line each, stacked, in a strip of a fixed smallest height, so a line
 * arriving or going does not move the map above it. There is no spinner in this
 * strip and there is none anywhere: a line that says what was asked and at which
 * address says the same thing and says it usefully. */
.map-origin {
  /* Never squashed. It is the line that says where every number on this screen
     came from, and half of it is worth nothing at all. */
  flex: 0 0 auto;
  display: grid;
  row-gap: var(--space-hair);
  min-height: 2.6em;
  margin: 0;
  padding: var(--space-1) var(--space-3);
  border-top: 1px solid var(--hairline);
  background: var(--surface-raised);
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-wrap: pretty;
}

.map-origin__line {
  margin: 0;
}

/* A generated map keeps nothing here until it has something to say — where it
 * came from is read in the panel now. An empty strip with a hairline above it
 * would be a band at the foot of the screen that means nothing. */
.map-origin:empty {
  display: none;
}

/* What the screen says while the map is on its way, or when it could not be
 * read. A sentence naming the address, never a spinner. */
.map-waiting {
  flex: 1 1 auto;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: var(--space-6) var(--space-3);
}

.map-waiting__line {
  margin: 0;
  max-width: 60ch;
  font-size: var(--text-md);
  color: var(--text-muted);
  text-wrap: pretty;
}

/* ---- Masthead: the product name and the one line under it ------------- */

.masthead {
  margin-bottom: var(--space-5);
}

