1	/**
2	 * The test that would have caught what Kent saw.
3	 *
4	 * On 2026-09-21 he ran the app with his own model key, pressed *Watch it build*,
5	 * and said *"i don't see anything happening after pressing watch it build"*.
6	 * Nothing was broken: the run's first event says only that the run has started
7	 * — it is sent before any model call and arrives at once — and the **first
8	 * proposal** comes back about twenty-three seconds later, with later ones fifty
9	 * to a hundred and ten seconds apart. In between the screen held one dashed
10	 * rectangle and nothing else, and the one sentence that said what the run was
11	 * doing was passed to the frame as *spoken only* and clipped by a stylesheet to
12	 * a one-pixel box.
13	 *
14	 * That is the shape of every test below: the run starts, and then nothing for
15	 * twenty-three seconds.
16	 *
17	 * **No test in the suite could have seen it.** Every browser test runs with an
18	 * empty model key and plays a recording at four tenths of a second an event, so
19	 * no test had ever met a real silence — and the one browser test that looked at
20	 * this element **asserted the clipping**.
21	 *
22	 * So this test injects the adverse timing instead of waiting for it: fake
23	 * timers, a real fold of the real events, and the screen rendered into a
24	 * simulated page. It is tier 2 of decision record 0008 — a change whose
25	 * correctness is about timing gets a no-browser twin that produces the bad
26	 * timing on purpose — and it holds four things:
27	 *
28	 * 1. the strip is **visible**, and the sentence a screen reader hears is the
29	 *    sentence on the page, in one element;
30	 * 2. after twenty-three seconds of silence it reads the wait, and it names what
31	 *    is being held open;
32	 * 3. an arrival starts the count again;
33	 * 4. **a replay shows no seconds**, because at the pace we set a replay at the
34	 *    number would reset twice a second and would be measuring our own pacing.
35	 *
36	 * It asserts no value anywhere. The seconds it checks are the seconds it
37	 * advanced the clock by, which is the same number read back through the product
38	 * rather than a figure written down here.
39	 */
40	
41	import { act, render, screen } from "@testing-library/react";
42	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
43	import { theOpeningLine, whatChanged } from "../../a11y/growth";
44	import type { WorldView } from "../../world";
45	import { inFewWords } from "../../world/naming";
46	import type { Activity, StreamEvent } from "../events";
47	import { GenerationScreen } from "../GenerationScreen";
48	import { fold, type Growth, waitingFor } from "../growth";
49	import type { TheRun, WhereItHasGot } from "../theRun";
50	import {
51	  A_VERY_LONG_THOUGHT,
52	  activity,
53	  FOUND,
54	  REFUSED,
55	  SEARCHING,
56	  STARTED,
57	  THE_GROWTH,
58	  THE_SENTENCE,
59	  THINKING,
60	} from "./aStream";
61	
62	// The map draws on a canvas the simulated page cannot measure, and what it draws
63	// has tests of its own. Here it stands in for itself: this file is about the
64	// foot of the screen.
65	vi.mock("../../graph/Canvas", () => ({
66	  MapCanvas: ({ world }: { world: WorldView }) => (
67	    <div data-testid="the-map">{`${world.claims.length} claims`}</div>
68	  ),
69	}));
70	
71	/**
72	 * A run somebody else is driving, so the test can hand it one event at a time.
73	 *
74	 * It is the real interface, with the real fold behind it and the real sentences
75	 * the live region says — everything but the request. Nothing here paces itself:
76	 * the only clock in this file is the fake one.
77	 */
78	function aRunWeDrive(): TheRun & { arrive: (event: StreamEvent | Activity) => void } {
79	  const opening = waitingFor(THE_SENTENCE, null);
80	  let where: WhereItHasGot = { growth: opening, saying: theOpeningLine(opening) };
81	  const watchers = new Set<() => void>();
82	  return {
83	    asked: { hypothesis: THE_SENTENCE, target: null, belief: null },
84	    press: "press 1",
85	    now: () => where,
86	    watch: (told: () => void) => {
87	      watchers.add(told);
88	      return () => {
89	        watchers.delete(told);
90	      };
91	    },
92	    letGo: () => {},
93	    arrive: (event: StreamEvent | Activity) => {
94	      const grown = fold(where.growth, event);
95	      where = { growth: grown, saying: sayingFor(where.growth, grown, where.saying) };
96	      for (const told of watchers) {
97	        told();
98	      }
99	    },
100	  };
101	}
102	
103	/** What the region says after this event, keeping the last line when nothing changed. */
104	function sayingFor(was: Growth, now: Growth, lastSaid: string): string {
105	  const said = whatChanged(was, now);
106	  return said === "" ? lastSaid : said;
107	}
108	
109	/** The strip's printed sentence — the same element the live region is. */
110	function theSentence(): HTMLElement {
111	  const said = document.querySelector(".run-strip .map-live");
112	  expect(said, "there is no strip at the foot of the screen").not.toBeNull();
113	  return said as HTMLElement;
114	}
115	
116	/** What the strip reads, whole: the word, the sentence and the reading. */
117	function theStrip(): HTMLElement {
118	  return document.querySelector(".run-strip") as HTMLElement;
119	}
120	
121	/** Move the fake clock on, letting React redraw whatever the ticks changed. */
122	function waitOut(seconds: number): void {
123	  act(() => {
124	    vi.advanceTimersByTime(seconds * 1000);
125	  });
126	}
127	
128	beforeEach(() => {
129	  vi.useFakeTimers();
130	});
131	
132	afterEach(() => {
133	  vi.useRealTimers();
134	});
135	
136	describe("the foot of the screen says what a live run is doing", () => {
137	  it("test_the_visible_strip_says_what_the_run_is_waiting_for", () => {
138	    const run = aRunWeDrive();
139	    render(
140	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
141	    );
142	
143	    // The run has started — that event is sent before any model call and
144	    // arrives at once — and no proposal has come back. This is the moment Kent
145	    // sat in front of for twenty-three seconds.
146	    act(() => {
147	      run.arrive(STARTED);
148	    });
149	
150	    // **Printed, not only spoken.** The sentence is inside the polite region
151	    // rather than beside a copy of it, so a change to one is a change to both.
152	    const said = theSentence();
153	    expect(said.getAttribute("aria-live")).toBe("polite");
154	    expect(said).toBeVisible();
155	    // And it is the run's own sentence, naming what is being held open.
156	    expect(said.textContent).toContain(THE_SENTENCE);
157	    expect(said.textContent).toContain("held open");
158	    // The state, in one word, in the box the foot already uses.
159	    expect(theStrip().getAttribute("data-state")).toBe("live");
160	
161	    // Twenty-three seconds of nothing at all.
162	    waitOut(23);
163	
164	    // The reading is what the clock was advanced by, read back through the
165	    // product. Nothing here is a figure somebody wrote down.
166	    expect(theStrip().textContent).toContain("nothing new on the map for 23 s");
167	    // It sits beside the region and never inside it: a number that ticked
168	    // inside a polite region would be announced once a second.
169	    expect(said.textContent).not.toContain("nothing new on the map for");
170	    expect(document.querySelector(".run-strip__waited")?.getAttribute("aria-hidden")).toBeNull();
171	  });
172	
173	  it("test_an_arrival_resets_the_count", () => {
174	    const run = aRunWeDrive();
175	    render(
176	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
177	    );
178	    act(() => {
179	      run.arrive(STARTED);
180	    });
181	    waitOut(23);
182	    expect(theStrip().textContent).toContain("nothing new on the map for 23 s");
183	
184	    // The first proposal lands.
185	    const first = THE_GROWTH[1];
186	    expect(first, "the worked run has no first proposal").toBeDefined();
187	    act(() => {
188	      run.arrive(first as StreamEvent);
189	    });
190	
191	    // The count starts again from the arrival, not from the press.
192	    expect(theStrip().textContent).toContain("nothing new on the map for 0 s");
193	    expect(theStrip().textContent).not.toContain("nothing new on the map for 23 s");
194	    // And the sentence says what arrived and what is now being worked on —
195	    // which is the frontier the event itself carried, never a guess.
196	    expect(theSentence().textContent).toContain("A claim arrived:");
197	    expect(theSentence().textContent).toContain("Working on what follows from");
198	
199	    // Four more seconds of silence, and the reading follows the clock.
200	    waitOut(4);
201	    expect(theStrip().textContent).toContain("nothing new on the map for 4 s");
202	  });
203	
204	  it("test_a_replay_shows_no_seconds", () => {
205	    const run = aRunWeDrive();
206	    render(
207	      <GenerationScreen run={run} replaying={true} onRunAgain={() => {}} onLeave={() => {}} />,
208	    );
209	    act(() => {
210	      run.arrive(STARTED);
211	    });
212	    waitOut(23);
213	
214	    // A replay is paced by the server, so a count of seconds would be measuring
215	    // our own pacing rather than any wait. The sentence is printed exactly as it
216	    // is on a live run; the reading is simply not there.
217	    expect(theStrip().getAttribute("data-state")).toBe("replay");
218	    expect(theSentence()).toBeVisible();
219	    expect(theSentence().textContent).toContain("held open");
220	    expect(theStrip().textContent).not.toContain("nothing new on the map for");
221	    expect(document.querySelector(".run-strip__waited")).toBeNull();
222	  });
223	
224	  it("test_a_finished_run_stops_counting_and_keeps_its_sentence", () => {
225	    const run = aRunWeDrive();
226	    render(
227	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
228	    );
229	    act(() => {
230	      for (const event of THE_GROWTH) {
231	        run.arrive(event);
232	      }
233	      run.arrive({ event: "done", reason: "reached_terminal", claims: 7, links: 8, rejected: 1 });
234	    });
235	
236	    // Nothing is being waited for any more, so there is nothing to measure.
237	    expect(theStrip().getAttribute("data-state")).toBe("finished");
238	    expect(document.querySelector(".run-strip__waited")).toBeNull();
239	    waitOut(30);
240	    expect(theStrip().textContent).not.toContain("nothing new on the map for");
241	
242	    // Why it stopped is said once, in the strip's own sentence, and printed
243	    // exactly once on the page. It used to be printed twice — once here and
244	    // once in a second strip of prose below it.
245	    const why = theSentence().textContent ?? "";
246	    expect(why).toContain("The map is finished");
247	    const printed = (document.body.textContent ?? "").split("The map is finished");
248	    expect(printed).toHaveLength(2);
249	  });
250	
251	  it("test_the_run_details_in_the_panel_do_not_claim_arrivals_on_an_empty_map", () => {
252	    const run = aRunWeDrive();
253	    render(
254	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
255	    );
256	    act(() => {
257	      run.arrive(STARTED);
258	    });
259	
260	    // Where this map is coming from is in the panel now, not in an always-on
261	    // strip at the foot — and what it says is true of a map with nothing on it,
262	    // which is what the line it replaced was not.
263	    expect(screen.getByText("Run details")).toBeVisible();
264	    const panel = document.querySelector(".inspector")?.textContent ?? "";
265	    expect(panel).toContain(STARTED.generation_id);
266	    expect(panel).toContain("/api/generate");
267	    expect(panel).toContain("Nothing on this map is typed in");
268	    expect(panel).not.toContain("arrived from");
269	
270	    // And nothing at the foot of the screen repeats it.
271	    expect(theStrip().textContent).not.toContain(STARTED.generation_id);
272	  });
273	});
274	
275	/**
276	 * The two quiet lines under the sentence, whichever of them is there.
277	 *
278	 * They are read by the class the strip draws them with rather than by their
279	 * words, so that a test that looks for words the strip never printed fails on
280	 * the words rather than on finding nothing at all.
281	 */
282	function theQuietLines(): HTMLElement[] {
283	  return [...document.querySelectorAll<HTMLElement>(".run-strip__doing-line")];
284	}
285	
286	/** Everything the two quiet lines say, joined, or the empty string when neither is there. */
287	function whatIsBeingDone(): string {
288	  return theQuietLines()
289	    .map((line) => line.textContent ?? "")
290	    .join(" ");
291	}
292	
293	describe("the foot of the screen says what the model is doing right now", () => {
294	  it("test_the_strip_prints_the_search_the_model_just_ran", () => {
295	    const run = aRunWeDrive();
296	    render(
297	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
298	    );
299	    act(() => {
300	      run.arrive(STARTED);
301	    });
302	
303	    // Fourteen seconds into a call that will take another two minutes, the
304	    // model issues a web search. This is the first thing in this product that
305	    // reaches the screen inside a call rather than at the end of one.
306	    act(() => {
307	      run.arrive(SEARCHING);
308	    });
309	    expect(whatIsBeingDone()).toContain(`searching the web: "${SEARCHING.text}"`);
310	
311	    // What came back replaces it: one line about the search, latest only, so
312	    // the strip never grows a list.
313	    act(() => {
314	      run.arrive(FOUND);
315	    });
316	    expect(whatIsBeingDone()).toContain(`found: ${FOUND.text}`);
317	    expect(whatIsBeingDone()).not.toContain(SEARCHING.text);
318	
319	    // And the count of silence is untouched by it: the counter measures how
320	    // long it has been since anything landed **on the map**, which is what its
321	    // words say, and an activity line lands on neither.
322	    waitOut(9);
323	    expect(theStrip().textContent).toContain("nothing new on the map for 9 s");
324	  });
325	
326	  it("test_the_thinking_line_is_the_models_own_words_and_says_so", () => {
327	    const run = aRunWeDrive();
328	    render(
329	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
330	    );
331	    act(() => {
332	      run.arrive(STARTED);
333	      run.arrive(THINKING);
334	    });
335	
336	    // Printed word for word, and labelled as the model's, because it is the one
337	    // line here about the model's mind rather than about a fact with a source.
338	    expect(whatIsBeingDone()).toContain(`the model, in its own words: ${THINKING.text}`);
339	
340	    // The two lines stand together: a search and a thought are two different
341	    // things and neither replaces the other.
342	    act(() => {
343	      run.arrive(SEARCHING);
344	    });
345	    expect(whatIsBeingDone()).toContain(SEARCHING.text);
346	    expect(whatIsBeingDone()).toContain(THINKING.text);
347	    expect(theQuietLines()).toHaveLength(2);
348	  });
349	
350	  it("test_a_long_line_is_cut_at_a_word_and_stays_one_line", () => {
351	    const run = aRunWeDrive();
352	    render(
353	      <GenerationScreen run={run} replaying={false} onRunAgain={() => {}} onLeave={() => {}} />,
354	    );
355	    act(() => {
356	      run.arrive(STARTED);
357	      run.arrive(A_VERY_LONG_THOUGHT);
358	    });
359	
360	    const printed = whatIsBeingDone();
361	    // Shorter than what arrived, ended with an ellipsis, and cut where a word
362	    // ends rather than through the middle of one.
363	    expect(printed).not.toContain(A_VERY_LONG_THOUGHT.text);
364	    expect(printed).toContain("…");
